<?php get_header(); the_post(); $terms = get_the_terms( get_the_ID(), 'program-type' ); $term = ( $terms && ! is_wp_error( $terms ) ) ? $terms[0] : null; $sections = get_post_meta( get_the_ID(), '_upm_sections', true ); ?><main class="upm-page"><div class="container upm-detail"><nav class="upm-breadcrumbs"><a href="<?php echo esc_url( home_url( '/' ) ); ?>" <?php echo upm_track_attr( 'link', 'home', 'breadcrumbs', 'componentLink' ); ?>>Home</a> / <a href="<?php echo esc_url( um_programs_url() ); ?>" <?php echo upm_track_attr( 'link', 'back-to-programmes', 'breadcrumbs', 'componentLink' ); ?>>Programmes</a> / <?php the_title(); ?></nav><div class="upm-detail__hero"><div><?php the_post_thumbnail( 'large' ); ?></div><div><h1><?php the_title(); ?></h1><?php if ( $term ) : ?><p><a href="<?php echo esc_url( um_programs_url( $term->slug ) ); ?>" <?php echo upm_track_attr( 'link', 'program-type', 'programme-overview', 'componentLink' ); ?>><?php echo esc_html( $term->name ); ?></a></p><?php endif; ?><div class="upm-meta"><span><strong>Academic year</strong><?php echo esc_html( get_post_meta( get_the_ID(), '_upm_academic_year', true ) ); ?></span><span><strong>Duration</strong><?php echo esc_html( get_post_meta( get_the_ID(), '_upm_duration', true ) ); ?></span></div><div class="upm-cta-row"><a class="btn btn--gold btn--pill" href="#enquire" <?php echo upm_track_attr( 'link', 'apply-now', 'programme-overview', 'componentLink' ); ?>>Apply now</a><button class="btn btn--gold btn--pill" type="button" data-enquire-toggle <?php echo upm_track_attr( 'button', 'open-enquiry-form', 'programme-overview', 'componentButton' ); ?>>Enquire now</button></div></div></div><section class="upm-section"><h2>About this programme</h2><?php the_content(); ?></section><?php if ( is_array( $sections ) ) : foreach ( $sections as $section ) : ?><section class="upm-section"><h2><?php echo esc_html( $section['title'] ?? '' ); ?></h2><?php if ( ! empty( $section['image'] ) ) : ?><p><?php echo wp_get_attachment_image( absint( $section['image'] ), 'large', false, array( 'class' => 'upm-section-image' ) ); ?></p><?php endif; ?><div><?php echo wp_kses_post( wpautop( $section['description'] ?? '' ) ); ?></div></section><?php endforeach; endif; ?><p><a href="<?php echo esc_url( um_programs_url() ); ?>" <?php echo upm_track_attr( 'link', 'back-to-programmes', 'programme-overview', 'componentLink' ); ?>>&larr; Back to programmes</a></p></div></main><?php get_footer();
